-- Supplier management reporting and measurable performance history.
create table public.order_status_history(id bigint generated always as identity primary key,order_id uuid not null references public.orders(id) on delete cascade,from_status public.order_status,to_status public.order_status not null,changed_at timestamptz not null default now());
alter table public.order_status_history enable row level security;create policy "admin order history read" on public.order_status_history for select using(public.is_platform_admin());
create or replace function public.capture_order_status_history()returns trigger language plpgsql security definer set search_path=public as $$begin if old.status is distinct from new.status then insert into public.order_status_history(order_id,from_status,to_status)values(new.id,old.status,new.status);end if;return new;end;$$;
create trigger order_status_history_capture after update of status on public.orders for each row execute function public.capture_order_status_history();
create index idx_order_status_history_order on public.order_status_history(order_id,changed_at);

create or replace function public.admin_refresh_supplier_performance(target_supplier uuid default null)returns integer language plpgsql security definer set search_path=public as $$
declare affected integer;begin if not public.admin_has_permission('reports')then raise exception 'Not authorised';end if;
insert into supplier_performance_metrics(supplier_id,order_count,completed_orders,cancelled_orders,disputed_orders,on_time_deliveries,rated_orders,average_rating,fulfilment_rate,cancellation_rate,dispute_rate,on_time_rate,acceptance_time_score,quotation_response_score,return_rate,stock_update_score,product_accuracy_score,score,rating,calculated_at)
select org.id,count(distinct o.id),count(distinct o.id)filter(where o.status='completed'),count(distinct o.id)filter(where o.status='cancelled'),count(distinct o.id)filter(where o.status='disputed'),count(distinct d.id)filter(where d.delivered_at is not null and(qr.required_date is null or d.delivered_at::date<=qr.required_date)),count(distinct rv.id),coalesce(avg(distinct rv.rating),0),case when count(distinct o.id)=0 then 0 else round(100.0*count(distinct o.id)filter(where o.status='completed')/count(distinct o.id),2)end,case when count(distinct o.id)=0 then 0 else round(100.0*count(distinct o.id)filter(where o.status='cancelled')/count(distinct o.id),2)end,case when count(distinct o.id)=0 then 0 else round(100.0*count(distinct o.id)filter(where o.status='disputed')/count(distinct o.id),2)end,case when count(distinct d.id)filter(where d.delivered_at is not null)=0 then 0 else round(100.0*count(distinct d.id)filter(where d.delivered_at is not null and(qr.required_date is null or d.delivered_at::date<=qr.required_date))/count(distinct d.id)filter(where d.delivered_at is not null),2)end,
coalesce((select greatest(0,100-avg(extract(epoch from(h2.changed_at-h1.changed_at))/3600)*4)from orders ox join order_status_history h1 on h1.order_id=ox.id and h1.to_status='paid' join order_status_history h2 on h2.order_id=ox.id and h2.to_status='confirmed' where ox.supplier_id=org.id),50),
coalesce((select greatest(0,100-avg(extract(epoch from(sq.created_at-rq.created_at))/3600)*2)from supplier_quotes sq join quote_requests rq on rq.id=sq.quote_request_id where sq.supplier_id=org.id),50),
case when count(distinct o.id)=0 then 0 else round(100.0*count(distinct o.id)filter(where o.status='return_requested')/count(distinct o.id),2)end,
coalesce((select round(100.0*count(*)filter(where sl.updated_at>=now()-interval'30 days')/nullif(count(*),0),2)from supplier_listings sl where sl.supplier_id=org.id),50),
greatest(0,100-case when count(distinct o.id)=0 then 0 else 100.0*count(distinct o.id)filter(where o.status='disputed')/count(distinct o.id)end),0,'needs_attention',now()
from organisations org left join orders o on o.supplier_id=org.id left join supplier_quotes sq0 on sq0.id=o.quote_id left join quote_requests qr on qr.id=sq0.quote_request_id left join deliveries d on d.order_id=o.id left join reviews rv on rv.supplier_id=org.id where org.organisation_type='supplier'and(target_supplier is null or org.id=target_supplier)group by org.id
on conflict(supplier_id)do update set order_count=excluded.order_count,completed_orders=excluded.completed_orders,cancelled_orders=excluded.cancelled_orders,disputed_orders=excluded.disputed_orders,on_time_deliveries=excluded.on_time_deliveries,rated_orders=excluded.rated_orders,average_rating=excluded.average_rating,fulfilment_rate=excluded.fulfilment_rate,cancellation_rate=excluded.cancellation_rate,dispute_rate=excluded.dispute_rate,on_time_rate=excluded.on_time_rate,acceptance_time_score=excluded.acceptance_time_score,quotation_response_score=excluded.quotation_response_score,return_rate=excluded.return_rate,stock_update_score=excluded.stock_update_score,product_accuracy_score=excluded.product_accuracy_score,calculated_at=now();get diagnostics affected=row_count;
update supplier_performance_metrics set score=round(acceptance_time_score*.10+quotation_response_score*.10+fulfilment_rate*.20+(100-cancellation_rate)*.10+(100-return_rate)*.10+(100-dispute_rate)*.10+on_time_rate*.10+least(100,average_rating*20)*.10+stock_update_score*.05+product_accuracy_score*.05,2)where(target_supplier is null or supplier_id=target_supplier);
update supplier_performance_metrics set rating=case when score>=85 then'excellent'when score>=70 then'good'when score>=50 then'needs_attention'else'high_risk'end where(target_supplier is null or supplier_id=target_supplier);return affected;end;$$;

create or replace function public.admin_list_suppliers(search_text text default null,status_filter text default null,region_filter text default null,category_filter text default null,performance_filter text default null,sort_by text default'newest',page_number integer default 1,page_size integer default 25)returns table(id uuid,business_name text,trading_name text,primary_contact text,phone text,email text,business_type text,region text,categories text[],verification_status text,verification_levels text[],product_count bigint,order_count bigint,total_sales numeric,fulfilment_rate numeric,average_rating numeric,settlement_status text,account_status text,registered_at timestamptz,performance_rating text,total_rows bigint)language plpgsql stable security definer set search_path=public as $$begin if not public.admin_has_permission('supplier_verification')then raise exception'Not authorised';end if;return query with base as(select o.id,o.name business_name,sp.trading_name,sp.primary_contact_name,sp.primary_phone,sp.business_email,sp.business_type::text,sp.region,sp.primary_categories,o.verification_status::text,o.verification_levels::text[],coalesce(l.product_count,0)product_count,coalesce(m.order_count,0)::bigint order_count,coalesce(s.total_sales,0)total_sales,coalesce(m.fulfilment_rate,0)fulfilment_rate,coalesce(m.average_rating,0)average_rating,case when o.settlement_hold then'held'when sd.organisation_id is null then'missing'else'ready'end settlement_status,o.account_status,o.created_at,coalesce(m.rating,'needs_attention')performance_rating from organisations o left join supplier_profiles sp on sp.organisation_id=o.id left join supplier_settlement_details sd on sd.organisation_id=o.id left join supplier_performance_metrics m on m.supplier_id=o.id left join lateral(select count(*)product_count from supplier_listings where supplier_id=o.id)l on true left join lateral(select coalesce(sum(total),0)total_sales from orders where supplier_id=o.id and status not in('cancelled','refunded'))s on true where o.organisation_type='supplier'),filtered as(select*,count(*)over()total_rows from base where(search_text is null or business_name ilike'%'||search_text||'%'or trading_name ilike'%'||search_text||'%'or primary_contact_name ilike'%'||search_text||'%'or business_email ilike'%'||search_text||'%')and(status_filter is null or verification_status=status_filter or account_status=status_filter)and(region_filter is null or region=region_filter)and(category_filter is null or category_filter=any(primary_categories))and(performance_filter is null or performance_rating=performance_filter))select f.id,f.business_name,f.trading_name,f.primary_contact_name,f.primary_phone,f.business_email,f.business_type,f.region,f.primary_categories,f.verification_status,f.verification_levels,f.product_count,f.order_count,f.total_sales,f.fulfilment_rate,f.average_rating,f.settlement_status,f.account_status,f.created_at,f.performance_rating,f.total_rows from filtered f order by case when sort_by='oldest'then f.created_at end asc,case when sort_by='highest_sales'then f.total_sales end desc,case when sort_by='most_orders'then f.order_count end desc,f.created_at desc offset greatest(page_number-1,0)*least(greatest(page_size,1),100)limit least(greatest(page_size,1),100);end;$$;

revoke all on function public.admin_refresh_supplier_performance(uuid),public.admin_list_suppliers(text,text,text,text,text,text,integer,integer)from public,anon;grant execute on function public.admin_refresh_supplier_performance(uuid),public.admin_list_suppliers(text,text,text,text,text,text,integer,integer)to authenticated;
revoke insert,update,delete on public.order_status_history from anon,authenticated;
